// 驱动端口：以业务用例命名，REST/MQ/Job 都调用这个契约
public interface PlaceOrderUseCase {
    OrderId placeOrder(PlaceOrderCommand command);
}

// 被驱动端口：返回领域对象和领域标识，不暴露 JPA Entity 或 SQL 细节
public interface OrderRepository {
    Optional<Order> findById(OrderId id);
    void save(Order order);
}

public interface PaymentGateway {
    PaymentResult authorize(PaymentCommand command);
}

public interface DomainEventPublisher {
    void publish(List<DomainEvent> events);
}

// 应用服务：实现用例端口，处理事务边界、领域对象调用和外部端口编排
public class OrderApplicationService implements PlaceOrderUseCase {
    private final OrderRepository orderRepository;
    private final PaymentGateway paymentGateway;
    private final DomainEventPublisher eventPublisher;

    public OrderApplicationService(OrderRepository orderRepository,
                                   PaymentGateway paymentGateway,
                                   DomainEventPublisher eventPublisher) {
        this.orderRepository = orderRepository;
        this.paymentGateway = paymentGateway;
        this.eventPublisher = eventPublisher;
    }

    // 本地事务可以包住订单状态变更和仓储保存
    // 支付授权、事件投递等远程副作用需要结合幂等或 Outbox 设计
    @Transactional
    @Override
    public OrderId placeOrder(PlaceOrderCommand command) {
        Order order = Order.create(command.customerId(), command.items());
        PaymentResult payment = paymentGateway.authorize(PaymentCommand.from(order));
        order.markPaid(payment.transactionId());
        orderRepository.save(order);
        eventPublisher.publish(order.pullDomainEvents());
        return order.id();
    }
}

// 被驱动适配器：JPA 实现仓储端口，负责 Entity 与 Domain 的双向转换
@Repository
public class JpaOrderRepository implements OrderRepository {
    private final SpringDataOrderJpaRepository jpaRepository;

    public JpaOrderRepository(SpringDataOrderJpaRepository jpaRepository) {
        this.jpaRepository = jpaRepository;
    }

    @Override
    public Optional<Order> findById(OrderId id) {
        return jpaRepository.findById(id.value()).map(OrderMapper::toDomain);
    }

    @Override
    public void save(Order order) {
        jpaRepository.save(OrderMapper.toEntity(order));
    }
}

// 驱动适配器：Controller 只做协议对象到命令对象的转换
@RestController
@RequestMapping("/orders")
public class OrderController {
    private final PlaceOrderUseCase placeOrderUseCase;

    public OrderController(PlaceOrderUseCase placeOrderUseCase) {
        this.placeOrderUseCase = placeOrderUseCase;
    }

    @PostMapping
    public OrderIdResponse create(@RequestBody CreateOrderRequest request) {
        OrderId id = placeOrderUseCase.placeOrder(request.toCommand());
        return new OrderIdResponse(id.value());
    }
}

// 单元测试：直接替换三个端口实现，不需要启动 Web 容器、数据库或消息中间件
@Test
void placeOrderPublishesEventWithoutDatabaseOrHttp() {
    OrderRepository repository = mock(OrderRepository.class);
    PaymentGateway paymentGateway = command -> PaymentResult.authorized("tx-001");
    DomainEventPublisher publisher = mock(DomainEventPublisher.class);
    PlaceOrderUseCase useCase = new OrderApplicationService(repository, paymentGateway, publisher);

    OrderId id = useCase.placeOrder(new PlaceOrderCommand(new CustomerId("c-1"), List.of(new OrderItem("sku-1", 1))));

    assertNotNull(id);
    verify(repository).save(any(Order.class));
    verify(publisher).publish(argThat(events -> events.stream().anyMatch(e -> e instanceof OrderPaidEvent)));
}
